            border = grid[top][mid]
            if border == 0 or grid[top][mid - 1] != border or grid[top][mid + 1] != border:
                continue

            # The central border cell must connect to a vertical stem above.
            r = top - 1
            while r >= 0 and grid[r][mid] == border:
                r -= 1
            if top < 3 or r > 0:
                continue

            # Find the box's bottom edge, with both side borders intact.
            bottom = top + 1
            while bottom < h and grid[bottom][mid - 1] == border and grid[bottom][mid + 1] == border:
                bottom += 1
            bottom -= 1
            if bottom <= top + 1 or grid[bottom][mid] != border:
                continue

            for rr in range(top + 1, bottom):
                if grid[rr][mid] != border:
                    out[rr][mid] = 4
    return out
