def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    # Find background-colored regions that are completely enclosed by the
    # non-background outline, then fill those cavities with 4.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            region = []
            touches_edge = False
            while stack:
                y, x = stack.pop()
                region.append((y, x))
                if y == 0 or y == h - 1 or x == 0 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == grid[r][c] and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if not touches_edge and grid[r][c] != 4:
                for y, x in region:
                    out[y][x] = 4
    return out
