    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))

    # Mark background-colored cells reachable from the edge.
    exterior = set()
    stack = []
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == bg and (r, c) not in exterior:
                exterior.add((r, c))
                stack.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == bg and (r, c) not in exterior:
                exterior.add((r, c))
                stack.append((r, c))

    while stack:
        r, c = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and
                    grid[nr][nc] == bg and (nr, nc) not in exterior):
                exterior.add((nr, nc))
                stack.append((nr, nc))

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and (r, c) not in exterior:
                out[r][c] = 4
    return out
